css:
.ej2705-container {
  font-family: "Source Sans 3", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  color: #1c2b30;
  background-color: #f4f6f9;
  padding: 18px;
  border-radius: 10px;
  max-width: 1180px;
  margin: 0 auto;
}
.ej2705-header { border-bottom: 3px solid #2f6b4f; padding-bottom: 12px; margin-bottom: 16px; }
.ej2705-header h1 { font-size: 1.6rem; margin: 0 0 4px 0; color: #1f4a36; }
.ej2705-subtitle { font-size: 1rem; margin: 0 0 10px 0; color: #3c5058; }
.ej2705-voice { font-size: 0.94rem; margin: 0; color: #2a3d44; }
.ej2705-badge {
  display: inline-block;
  background-color: #2f6b4f;
  color: #ffffff;
  border-radius: 4px;
  padding: 2px 8px;
  margin-right: 6px;
  font-weight: 600;
}
.ej2705-status {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 10px;
  margin-bottom: 18px;
}
.ej2705-card {
  background-color: #ffffff;
  border: 1px solid #cfd8e3;
  border-left: 4px solid #2f6b4f;
  border-radius: 8px;
  padding: 10px 12px;
}
.ej2705-card-label { font-size: 0.82rem; color: #47585f; margin-bottom: 3px; }
.ej2705-card-value { font-size: 1.32rem; font-weight: 700; color: #1f4a36; }
.ej2705-card-sub { font-size: 0.8rem; color: #55666d; margin-top: 2px; }
.ej2705-score { color: #9a3412; }
.ej2705-round {
  background-color: #ffffff;
  border: 1px solid #cfd8e3;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}
.ej2705-round-title { font-size: 1.16rem; margin: 0 0 8px 0; color: #1f4a36; }
.ej2705-brief {
  font-size: 0.95rem;
  line-height: 1.55;
  color: #26383f;
  background-color: #eef6ef;
  border-left: 3px solid #2f6b4f;
  padding: 10px 12px;
  border-radius: 0 6px 6px 0;
  margin: 0 0 14px 0;
}
.ej2705-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(230px, 1fr));
  gap: 12px;
}
.ej2705-field { display: flex; flex-direction: column; }
.ej2705-field label { font-size: 0.87rem; font-weight: 600; color: #2a3d44; margin-bottom: 4px; }
.ej2705-container select {
  background-color: #ffffff;
  color: #1c2b30;
  border: 1px solid #7d949c;
  border-radius: 5px;
  padding: 7px 8px;
  font-size: 0.94rem;
  width: 100%;
}
.ej2705-container option { background-color: #ffffff; color: #1c2b30; }
.ej2705-note { font-size: 0.84rem; color: #4d5f66; margin: 12px 0 0 0; font-style: italic; }
.ej2705-actions { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.ej2705-btn-primary {
  background-color: #2f6b4f;
  color: #ffffff;
  border: 1px solid #2f6b4f;
  border-radius: 6px;
  padding: 10px 20px;
  font-size: 0.97rem;
  font-weight: 600;
  cursor: pointer;
}
.ej2705-btn-primary:hover { background-color: #1f4a36; }
.ej2705-container button:disabled { opacity: 0.55; cursor: not-allowed; }
.ej2705-container :focus-visible { outline: 3px solid #9a3412; outline-offset: 2px; }
.ej2705-history {
  background-color: #ffffff;
  border: 1px solid #cfd8e3;
  border-radius: 8px;
  padding: 12px;
}
.ej2705-history table { width: 100%; border-collapse: collapse; font-size: 0.88rem; color: #1c2b30; }
.ej2705-history th {
  text-align: left;
  background-color: #eef6ef;
  color: #1c2b30;
  border-bottom: 2px solid #cfd8e3;
  padding: 6px 8px;
}
.ej2705-history td { border-bottom: 1px solid #dfe5ec; padding: 6px 8px; }
.ej2705-cm { font-size: 0.96rem; color: #1c2b30; }
.ej2705-cm-score { font-size: 2.3rem; font-weight: 800; color: #1f4a36; }
.ej2705-cm-max { font-size: 1.05rem; font-weight: 600; color: #55666d; }
.ej2705-cm-verdict { font-size: 1.1rem; font-weight: 700; color: #9a3412; margin-bottom: 10px; }
.ej2705-cm-kpis { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; }
.ej2705-cm-kpi {
  background-color: #eef6ef;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 0.88rem;
  color: #26383f;
}
.ej2705-cm-debrief { font-weight: 700; margin: 10px 0 4px 0; color: #1f4a36; }
.ej2705-cm-insights { margin: 0; padding-left: 20px; line-height: 1.55; }
.ej2705-charts {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}
.ej2705-chart {
  background-color: #ffffff;
  border: 1px solid #cfd8e3;
  border-radius: 8px;
  padding: 12px;
}
@media (prefers-reduced-motion: reduce) {
  .ej2705-container * { transition: none !important; animation: none !important; }
}

