            out.be = ds.last.be;
            out.hours = ds.last.hours;
            if (period >= state.maxPeriods) { ds.finished = true; }
            var self = this;
            var nextP = (state.domainState && state.domainState.finished) ? state.currentPeriod : state.currentPeriod + 1;
            setTimeout(function() { self._updateBriefing(window.mySimulation.state, nextP); }, 300);
            return out;
        }

        _flat(state, upto) {
            var d = (state && state.decisions) || {};
            var out = {};
            var p, k;
            for (p = 1; p <= upto; p++) {
                var r = d['round' + p];
                if (r) { for (k in r) { if (Object.prototype.hasOwnProperty.call(r, k)) { out[k] = r[k]; } } }
            }
            return out;
        }

        _active(dec, k, g) {
            if (this.ROUND_OF[g] <= k) {
                var v = dec[g];
                return (v === undefined || v === null) ? this.DEFAULTS[g] : v;
            }
            return this.REF[g];
        }

        _annuity(bal, r, n) {
            if (n <= 0) { return bal; }
            if (r <= 0) { return bal / n; }
            return bal * r / (1.0 - Math.pow(1.0 + r, -n));
        }

        _event(dec, k) {
            var c = this.C;
            var a = {};
            var j, m;
            for (j = 0; j < this.KEYS.length; j++) { a[this.KEYS[j]] = this._active(dec, k, this.KEYS[j]); }
            var lo = this.LOCAL[a.local1];
            var fi = this.FIN[a.fin1];
            var su = this.SURT[a.surtido2];
            var pr = this.PRECIO[a.precio2];
            var shock = (k >= 4);
            var rent = lo[0];
            var fit = lo[2] - fi[4];
            var loan = fi[0];
            var rm = fi[1] / 12.0;
            var pay = (loan > 0) ? this._annuity(loan, rm, fi[2]) : 0.0;
            var deposit = this.DEPOSIT * rent;
            var stock = su[2];
            var cash = c.SAV + loan * (1.0 - fi[3]) - fit - lo[3] - deposit - c.SETUP - (fi[5] ? 0.0 : stock);
            var payStock = fi[5] ? stock : 0.0;
            var depM = fit / (c.DEP_YEARS * 12.0) + lo[3] / (c.FEE_YEARS * 12.0);
            var low = cash;
            var totS = 0.0, totGm = 0.0, totFix = 0.0, profit = 0.0, hours = 0.0, wasteT = 0.0, finT = 0.0;
            var payables = 0.0;
            var nv = this.NAV[a.navidad4];
            for (m = 1; m <= 12; m++) {
                var pe = (m >= this.M_FROM3) ? this.PERS[a.personal3] : this.PERS[this.REF.personal3];
                var co = (m >= this.M_FROM3) ? this.COMP[a.compras3] : this.COMP[this.REF.compras3];
                var ce = (shock && m >= this.M_FROM4) ? this.COMPET[a.compet4] : this.NOCOMPET;
                var ramp = (m <= lo[4]) ? c.RAMP[m - 1] : 1.0;
                if (a.local1 === 'traspaso' && m === 1) { ramp = 0.9; }
                var pf = pr[0], pm = pr[1];
                if (a.precio2 === 'promo' && m <= this.PROMO[0]) { pf = this.PROMO[1]; pm = this.PROMO[2]; }
                var xf = (m === this.M_XMAS) ? nv[0] : 1.0;
                var sales = lo[1] * su[0] * pf * pe[1] * ce[0] * c.SEAS[m - 1] * ramp * xf;
                var rate = su[1] + pm - fi[6] + co[0] + ce[1] + ((m === this.M_XMAS) ? nv[3] : 0.0);
                var wr = su[3] + co[1] + ce[4];
                var waste = sales * wr + ((m === this.M_XMAS + 1) ? nv[4] : 0.0);
                var gm = sales * rate - waste;
                var fixed = rent + c.OTHER + c.RETA + pe[0] + ce[2] + c.DRAW;
                var intr = 0.0, princ = 0.0;
                if (loan > 1e-6) {
                    intr = loan * rm;
                    princ = Math.min(pay - intr, loan);
                    loan -= princ;
                }
                var od = Math.max(-cash, 0.0) * c.OD;
                var pmo = gm - fixed - depM - intr - od;
                var dstock = 0.0;
                if (m === this.M_FROM3) {
                    dstock += su[2] * co[2];
                    if (co[3] > 0) {
                        payables = sales / 30.0 * co[3] * (1.0 - rate);
                        dstock -= payables;
                    }
                }
                if (shock && m === this.M_FROM4) { dstock += ce[3]; }
                if (m === nv[2]) { dstock += nv[1]; }
                if (m === fi[5]) { dstock += payStock; }
                cash += pmo + depM - princ - dstock;
                low = Math.min(low, cash);
                totS += sales; totGm += gm; totFix += fixed + depM + intr + od; profit += pmo;
                hours += pe[2] + co[4]; wasteT += waste; finT += intr + od;
            }
            var cmr = (totS > 0) ? totGm / totS : 0.0;
            var be = (cmr > 0) ? totFix / cmr : 1e12;
            var safety = (totS > 0) ? (totS - be) / totS : -1.0;
            var hard = 0;
            for (j = 0; j < this.HARD.length; j++) {
                var gk = this.HARD[j][0];
                if (a[gk] === this.HARD[j][1] && k >= this.ROUND_OF[gk]) { hard += 1; }
            }
            return { k: k, a: a, profit: profit, cash: cash, low: low, safety: safety, be: be, sales: totS, gm: totGm,
                     cmr: cmr, hours: hours / 12.0, waste: wasteT, fin: finT, loan: loan, hard: hard, fixed: totFix };
        }

        _components(r) {
            var c = this.C;
            return [this._clamp((r.profit - c.P_LO) / (c.P_HI - c.P_LO), 0, 1),
                    this._clamp((r.cash - c.K_LO) / (c.K_HI - c.K_LO), 0, 1),
                    this._clamp((r.safety - c.S_LO) / (c.S_HI - c.S_LO), 0, 1),
                    this._clamp((c.H_LO - r.hours) / (c.H_LO - c.H_HI), 0, 1)];
        }

        _roundScore(state, period) {
            var c = this.C;
            var m = this._event(this._flat(state, period), period);
            var comps = this._components(m);
            var w = [c.W_P, c.W_C, c.W_S, c.W_H];
            var tw = 0, num = 0, i;
            for (i = 0; i < 4; i++) { tw += w[i]; num += w[i] * comps[i]; }
            var score = this._clamp(100.0 * num / tw, 0, 100);
            if (m.hard > 0) {
                score = Math.min(score, c.CAP1 - c.CAP_STEP * (m.hard - 1));
            }
            return { score: this._jsround(score), m: m };
        }

        _completed(state) {
            var d = (state && state.decisions) || {};
            var n = 0;
            while (n < this.ROUNDS.length && d['round' + (n + 1)]) { n += 1; }
            return n;
        }

        _composite(state) {
            var n = this._completed(state);
            if (n === 0) { return 0; }
            var w = this.C.ROUND_WEIGHTS;
            var num = 0, den = 0, p;
            for (p = 1; p <= n; p++) {
                var r = this._roundScore(state, p);
                num += w[p - 1] * r.score;
                den += w[p - 1];
            }
            return this._clamp(this._jsround(num / den), 0, 100);
        }

        _verdictKey(score) {
            if (score >= this.C.THRESH_EXCELLENT) { return 'verdict_excellent'; }
            if (score >= this.C.THRESH_GOOD) { return 'verdict_good'; }
            if (score >= this.C.THRESH_DEVELOPING) { return 'verdict_developing'; }
            return 'verdict_beginner';
        }

        _jsround(x) {
            return (x >= 0) ? Math.floor(x + 0.5) : Math.ceil(x - 0.5);
        }

        _clamp(x, lo, hi) {
            if (x < lo) { return lo; }
            if (x > hi) { return hi; }
            return x;
        }

        _str(id, fallback) {
            var el = document.getElementById(id);
            return (el && el.value) ? el.value : fallback;
        }

        _t(key) {
            var sim = window.mySimulation;
            return (sim && sim.t) ? sim.t(key) : key;
        }

        _lang() {
            var sim = window.mySimulation;
            return (sim && sim.language) ? sim.language : 'es';
        }

        _fmtInt(n) {
            var v = Math.round(Math.abs(n));
            var s = String(v);
            var sep = (this._lang() === 'en') ? ',' : '.';
            var out = '';
            var i, k = 0;
            for (i = s.length - 1; i >= 0; i--) {
                out = s.charAt(i) + out;
                k += 1;
                if (k % 3 === 0 && i > 0) { out = sep + out; }
            }
            return (n < 0 && v > 0 ? '-' : '') + out;
        }

        _fmtDec(n) {
            var v = Math.round(n * 10) / 10;
            var whole = Math.floor(Math.abs(v));
            var dec = Math.round((Math.abs(v) - whole) * 10);
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + String(dec);
            return (v < 0 ? '-' : '') + s;
        }

        _r1(x) {
            return this._jsround(x * 10.0) / 10.0;
        }

        _r2(x) {
            return this._jsround(x * 100.0) / 100.0;
        }

        _fmtDec2(n) {
            var v = this._r2(n);
            var neg = v < 0;
            var cents = Math.round(Math.abs(v) * 100);
            var whole = Math.floor(cents / 100);
            var dec = cents - whole * 100;
            var s = String(whole) + ((this._lang() === 'en') ? '.' : ',') + (dec < 10 ? '0' : '') + String(dec);
            return (neg && cents > 0 ? '-' : '') + s;
        }

        _fmtPct1(n) {
            return this._fmtDec(n) + ((this._lang() === 'en') ? '%' : ' %');
        }

        _fmtMoney(n) {
            var v = Math.round(n);
            var body = this._fmtInt(Math.abs(v));
            if (this._lang() === 'en') { return (v < 0 ? '-' : '') + '€' + body; }
            return (v < 0 ? '-' : '') + body + ' €';
        }

        _syncControlsFromDecisions(state) {
            var period = (state && state.currentPeriod) || 1;
            var d = (state && state.decisions) || {};
            var k = d['round' + period] || {};
            (this.CONTROLS[period] || []).forEach(function(key) {
                var el = document.getElementById(key);
                if (el && k[key]) { el.value = k[key]; }
            });
        }

        _set(id, text) {
            var el = document.getElementById(id);
            if (el) { el.textContent = text; }
        }

        _updateBriefing(state, forcedPeriod) {
            if (!state) { return; }
            var ds = state.domainState || {};
            var period = forcedPeriod || state.currentPeriod || 1;
            var done = !!ds.finished;
            var nameEl = document.getElementById('roundName');
            if (nameEl) {
                nameEl.textContent = done ? this._t('round_done')
                    : this._t((this.ROUNDS[period - 1] || this.ROUNDS[0]).nameKey);
            }
            var pH = ds.profitHistory || [];
            var cH = ds.cashHistory || [];
            var sH = ds.safetyHistory || [];
            var bH = ds.beHistory || [];
            var hH = ds.hoursHistory || [];
            var n = pH.length;
            this._set('profitDisplay', n ? this._fmtMoney(pH[n - 1]) : '-');
            this._set('cashDisplay', n ? this._fmtMoney(cH[n - 1]) : '-');
            this._set('safetyDisplay', n ? this._fmtPct1(sH[n - 1]) : '-');
            this._set('beDisplay', n ? this._fmtMoney(bH[n - 1]) : '-');
            this._set('hoursDisplay', n ? this._fmtDec(hH[n - 1]) : '-');
            var sc = (ds.performance && ds.performance.overallScore) || 0;
            this._set('scoreDisplay', String(sc));
            var i;
            for (i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) { panel.style.display = (!done && (i + 1) === period) ? '' : 'none'; }
            }
            var actions = document.getElementById('actionsRow');
            if (actions) { actions.style.display = done ? 'none' : ''; }
            this._syncControlsFromDecisions(state);
        }

        _fbKey(g, v) {
            var pfx = { local1: 'lo', fin1: 'fi', surtido2: 'su', precio2: 'pr', personal3: 'pe', compras3: 'co', compet4: 'ce', navidad4: 'na' };
            var opts = {
                local1: ['centro', 'mercado', 'barrio', 'traspaso'],
                fin1: ['ahorro', 'banco', 'proveedor', 'tarjeta'],
                surtido2: ['amplio', 'fresco', 'gourmet', 'basico'],
                precio2: ['super', 'coste', 'premium', 'promo'],
                personal3: ['sola', 'parcial', 'completo', 'sinalta'],
                compras3: ['cashcarry', 'distribuidor', 'volumen', 'mercado'],
                compet4: ['diferenciar', 'precios', 'nada', 'ampliar'],
                navidad4: ['pedido', 'grande', 'sin', 'negro']
            };
            var keys = {
                fb_lo_centro: 1, fb_lo_mercado: 1, fb_lo_barrio: 1, fb_lo_traspaso: 1,
                fb_fi_ahorro: 1, fb_fi_banco: 1, fb_fi_proveedor: 1, fb_fi_tarjeta: 1,
                fb_su_amplio: 1, fb_su_fresco: 1, fb_su_gourmet: 1, fb_su_basico: 1,
                fb_pr_super: 1, fb_pr_coste: 1, fb_pr_premium: 1, fb_pr_promo: 1,
                fb_pe_sola: 1, fb_pe_parcial: 1, fb_pe_completo: 1, fb_pe_sinalta: 1,
                fb_co_cashcarry: 1, fb_co_distribuidor: 1, fb_co_volumen: 1, fb_co_mercado: 1,
                fb_ce_diferenciar: 1, fb_ce_precios: 1, fb_ce_nada: 1, fb_ce_ampliar: 1,
                fb_na_pedido: 1, fb_na_grande: 1, fb_na_sin: 1, fb_na_negro: 1
            };
            if (!opts[g] || opts[g].indexOf(v) < 0) { return 'fb_next'; }
            var key = 'fb_' + pfx[g] + '_' + v;
            return keys[key] ? key : 'fb_next';
        }

        getHint(state, results) {
            var p = (results && results.period) || 1;
            var m = this._event(this._flat(state, p), p);
            var a = m.a;
            if (m.hard > 0) { return this._t('hint_cap'); }
            var ctl = this.CONTROLS[p] || [];
            var i;
            for (i = 0; i < ctl.length; i++) {
                if (a[ctl[i]] !== this.BEST[ctl[i]]) { return this._t(this._fbKey(ctl[i], a[ctl[i]])); }
            }
            return null;
        }

