                + '<div class="ej2705-cm-kpis">'
                + '<div class="ej2705-cm-kpi">' + this._t('cm_kpi_profit') + ' <strong>' + this._fmtMoney(s.profit || 0) + '</strong></div>'
                + '<div class="ej2705-cm-kpi">' + this._t('cm_kpi_cash') + ' <strong>' + this._fmtMoney(s.cash || 0) + '</strong></div>'
                + '<div class="ej2705-cm-kpi">' + this._t('cm_kpi_safety') + ' <strong>' + this._fmtPct1(s.safety || 0) + '</strong></div>'
                + '<div class="ej2705-cm-kpi">' + this._t('cm_kpi_be') + ' <strong>' + this._fmtMoney(s.be || 0) + '</strong></div>'
                + '<div class="ej2705-cm-kpi">' + this._t('cm_kpi_hours') + ' <strong>' + this._fmtDec(s.hours || 0) + '</strong></div>'
                + '</div>'
                + '<div class="ej2705-cm-debrief">' + this._t('cm_debrief') + '</div>'
                + '<ul class="ej2705-cm-insights">' + items + '</ul>'
                + '</div>';
        }

